<script>
(()=>{
    const rows=[...document.querySelectorAll('[data-product]')],box=document.getElementById('cart-items'),count=document.getElementById('cart-count'),totalEl=document.getElementById('cart-total'),money=n=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(n),products=new Map(rows.map(row=>[row.dataset.product,{id:row.dataset.product,name:row.dataset.name,price:+row.dataset.price,stock:+row.dataset.stock,input:row.querySelector('.cart-quantity'),add:row.querySelector('.add-cart')} ]));
    function esc(value){const element=document.createElement('div');element.textContent=value;return element.innerHTML}
    function draw(){const selected=[...products.values()].filter(product=>+product.input.value),quantity=selected.reduce((sum,product)=>sum+(+product.input.value),0),total=selected.reduce((sum,product)=>sum+product.price*(+product.input.value),0);count.textContent=`${quantity} ${quantity===1?'item':'items'}`;totalEl.textContent=money(total);box.innerHTML=selected.length?selected.map(product=>`<div class="cart-line"><span><b>${esc(product.name)}</b><small>${money(product.price)} each</small></span><div class="cart-controls"><button type="button" data-id="${product.id}" data-step="-1">−</button><b>${product.input.value}</b><button type="button" data-id="${product.id}" data-step="1">+</button></div></div>`).join(''):'<p>Your cart is empty.</p>';products.forEach(product=>product.add.disabled=+product.input.value>=product.stock);document.getElementById('payment_reference').dispatchEvent(new Event('input'))}
    function adjust(id,step){const product=products.get(id);product.input.value=Math.max(0,Math.min(product.stock,+product.input.value+step));draw()}
    rows.forEach(row=>row.querySelector('.add-cart').addEventListener('click',()=>adjust(row.dataset.product,1)));box.addEventListener('click',event=>{const button=event.target.closest('[data-step]');if(button)adjust(button.dataset.id,+button.dataset.step)});draw();
})();
</script>
<script>
(()=>{
    const methods=[...document.querySelectorAll('input[name="payment_method"]')],cashFields=document.getElementById('cash-fields'),gcashFields=document.getElementById('gcash-fields'),cash=document.getElementById('cash_received'),reference=document.getElementById('payment_reference'),submit=document.getElementById('checkout-button'),note=document.getElementById('payment-note'),change=document.getElementById('change-due'),money=n=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(n);
    function updatePayment(){
        const method=document.querySelector('input[name="payment_method"]:checked')?.value||'cash',inputs=[...document.querySelectorAll('.cart-quantity')],rows=[...document.querySelectorAll('[data-product]')],qty=inputs.reduce((sum,input)=>sum+(+input.value||0),0),total=rows.reduce((sum,row)=>sum+(+row.dataset.price)*(+row.querySelector('.cart-quantity').value||0),0),paid=+(cash.value||0),hasReference=/^\d{13}$/.test(reference.value),isCash=method==='cash';
        cashFields.hidden=!isCash;gcashFields.hidden=isCash;cash.required=isCash;reference.required=!isCash;
        if(isCash){change.textContent=money(qty&&paid>=total?paid-total:0);submit.disabled=!(qty&&paid>=total);note.textContent=!qty?'Add products to the cart.':!paid?'Enter the customer’s cash.':paid<total?`Cash is short by ${money(total-paid)}.`:`Give ${money(paid-total)} change.`}
        else{submit.disabled=!(qty&&hasReference);note.textContent=!qty?'Add products to the cart.':!hasReference?'Enter the complete 13-digit GCash transaction reference.':'GCash reference verified. Confirm the payment before completing the sale.'}
        submit.firstChild.textContent=isCash?'Complete cash sale ':'Complete GCash sale ';
    }
    methods.forEach(input=>input.addEventListener('change',updatePayment));cash.addEventListener('input',updatePayment);reference.addEventListener('input',()=>{reference.value=reference.value.replace(/\D/g,'').slice(0,13);updatePayment()});updatePayment();
})();
</script>
